class_name VoxelWorldData
extends RefCounted

## Pure block storage, deterministic generation, voxel raycasting, and the
## save-document representation. This module deliberately has no scene, input,
## or rendering dependency so it can be tested in a headless process.
##
## The external implementation agent receives this interface and the behavior
## in its task file, but not the acceptance tests.

const WIDTH := 32
const HEIGHT := 16
const DEPTH := 32
const MAX_DIMENSION := 64
const AIR := 0
const GRASS := 1
const DIRT := 2
const STONE := 3
const LOG := 4
const LEAVES := 5
const SAVE_VERSION := 1
const BLOCK_NAMES := {
	0: "air",
	1: "grass",
	2: "dirt",
	3: "stone",
	4: "log",
	5: "leaves",
}

const RAY_EPSILON := 0.0000001
const MAX_RAY_STEPS := 1000000

var width: int = WIDTH
var height: int = HEIGHT
var depth: int = DEPTH
var world_seed: int = 0
var blocks := PackedByteArray()
var base_blocks := PackedByteArray()


func _init(size_x: int = WIDTH, size_y: int = HEIGHT, size_z: int = DEPTH) -> void:
	width = clampi(size_x, 1, MAX_DIMENSION)
	height = clampi(size_y, 1, MAX_DIMENSION)
	depth = clampi(size_z, 1, MAX_DIMENSION)
	blocks.resize(width * height * depth)
	base_blocks.resize(width * height * depth)


## X is the fastest-changing axis, then Z, then Y. This makes a simple
## y/z/x scan produce the deterministic order required by changed_blocks().
func index(x: int, y: int, z: int) -> int:
	return x + width * (z + depth * y)


func is_inside(x: int, y: int, z: int) -> bool:
	return x >= 0 and x < width and y >= 0 and y < height and z >= 0 and z < depth


func get_block(x: int, y: int, z: int) -> int:
	if not is_inside(x, y, z):
		return AIR
	return int(blocks[index(x, y, z)])


func set_block(x: int, y: int, z: int, block_id: int) -> bool:
	if not is_inside(x, y, z):
		return false
	if block_id < AIR or block_id > LEAVES:
		return false
	blocks[index(x, y, z)] = block_id
	return true


## Replace the generated terrain. Must be deterministic for a given seed and
## must include grass, dirt, stone, at least one log column, and height
## variation across the 32 x 32 surface.
func generate(seed_value: int) -> void:
	world_seed = seed_value
	_ensure_storage()
	blocks.fill(AIR)

	for z in range(depth):
		for x in range(width):
			var top := _surface_height(x, z)
			var surface_id := STONE
			for y in range(top + 1):
				if y == top:
					surface_id = GRASS
				elif y >= top - 2:
					surface_id = DIRT
				else:
					surface_id = STONE
				blocks[index(x, y, z)] = surface_id

	_place_trees()
	_clear_spawn_region()
	base_blocks = blocks.duplicate()


func highest_solid_y(x: int, z: int) -> int:
	if x < 0 or x >= width or z < 0 or z >= depth:
		return -1
	for y in range(height - 1, -1, -1):
		if get_block(x, y, z) != AIR:
			return y
	return -1


## Feet position in world space. The block below must be solid and the player
## capsule must have two empty cells above it.
func spawn_point() -> Vector3:
	var center_x := _spawn_center_x()
	var center_z := _spawn_center_z()
	var max_radius := maxi(width, depth)

	# First prefer ordinary ground, then fall back to any safe column (for
	# example when the player has built a pillar straight up from the centre).
	for allow_tree_blocks in [false, true]:
		for radius in range(max_radius + 1):
			for dz in range(-radius, radius + 1):
				for dx in range(-radius, radius + 1):
					if maxi(absi(dx), absi(dz)) != radius:
						continue
					var x := center_x + dx
					var z := center_z + dz
					if not is_inside(x, 0, z):
						continue
					var top := highest_solid_y(x, z)
					if top < 0 or top + 2 >= height:
						continue
					var top_id := get_block(x, top, z)
					if not allow_tree_blocks and (top_id == LOG or top_id == LEAVES):
						continue
					if get_block(x, top + 1, z) != AIR:
						continue
					if get_block(x, top + 2, z) != AIR:
						continue
					return Vector3(float(x) + 0.5, float(top) + 1.02, float(z) + 0.5)

	var fallback_top := highest_solid_y(center_x, center_z)
	if fallback_top < 0:
		fallback_top = 0
	return Vector3(
		float(center_x) + 0.5,
		float(fallback_top) + 1.02,
		float(center_z) + 0.5
	)


func counts() -> Dictionary:
	var result: Dictionary = {}
	for block_id in BLOCK_NAMES:
		result[String(BLOCK_NAMES[block_id])] = 0
	for value in blocks:
		var block_id := int(value)
		if BLOCK_NAMES.has(block_id):
			var key := String(BLOCK_NAMES[block_id])
			result[key] = int(result[key]) + 1
	return result


## Changes relative to the generated baseline, in deterministic y/z/x order.
## Removed baseline blocks appear with id 0.
func changed_blocks() -> Array:
	var result: Array = []
	var volume := mini(blocks.size(), base_blocks.size())
	for y in range(height):
		for z in range(depth):
			for x in range(width):
				var cell := index(x, y, z)
				if cell >= volume:
					continue
				var current := int(blocks[cell])
				var baseline := int(base_blocks[cell])
				if current != baseline:
					result.append({"x": x, "y": y, "z": z, "id": current})
	return result


func to_save_dict() -> Dictionary:
	return {
		"version": SAVE_VERSION,
		"world": {
			"width": width,
			"height": height,
			"depth": depth,
			"seed": world_seed,
		},
		"changes": changed_blocks(),
	}


## Validate and apply a save document atomically. Invalid input returns false
## and leaves the current world untouched.
##
## The parameter is intentionally untyped so that non-dictionary input (which
## the contract requires us to reject) arrives here as a value instead of
## triggering a typed-argument error before validation can run.
func apply_save(data) -> bool:
	if typeof(data) != TYPE_DICTIONARY:
		return false
	var document: Dictionary = data

	var version = _integer_value(document.get("version"))
	if version == null or int(version) != SAVE_VERSION:
		return false

	var world = document.get("world")
	if typeof(world) != TYPE_DICTIONARY:
		return false
	var world_document: Dictionary = world

	var saved_width = _integer_value(world_document.get("width"))
	var saved_height = _integer_value(world_document.get("height"))
	var saved_depth = _integer_value(world_document.get("depth"))
	var saved_seed = _integer_value(world_document.get("seed"))
	if saved_width == null or saved_height == null or saved_depth == null or saved_seed == null:
		return false
	if int(saved_width) != width or int(saved_height) != height or int(saved_depth) != depth:
		return false

	var changes = document.get("changes")
	if typeof(changes) != TYPE_ARRAY:
		return false
	var change_list: Array = changes
	if change_list.size() > width * height * depth:
		return false

	# Parse every cell before touching the live world. The temporary records
	# keep the apply phase free of any validation failure paths.
	var validated: Array = []
	for entry in change_list:
		if typeof(entry) != TYPE_DICTIONARY:
			return false
		var change: Dictionary = entry
		var cx = _integer_value(change.get("x"))
		var cy = _integer_value(change.get("y"))
		var cz = _integer_value(change.get("z"))
		var block_id = _integer_value(change.get("id"))
		if cx == null or cy == null or cz == null or block_id == null:
			return false
		if not is_inside(int(cx), int(cy), int(cz)):
			return false
		if int(block_id) < AIR or int(block_id) > LEAVES:
			return false
		validated.append({
			"x": int(cx),
			"y": int(cy),
			"z": int(cz),
			"id": int(block_id),
		})

	# Validation passed; regenerate the saved baseline and replay the edits.
	generate(int(saved_seed))
	for change in validated:
		set_block(int(change["x"]), int(change["y"]), int(change["z"]), int(change["id"]))
	return true


## Amanatides-Woo style grid traversal. Returns:
##   hit: bool
##   block: [x, y, z] (empty when no hit)
##   previous: [x, y, z] (empty when no hit)
##   normal: [x, y, z] (axis from previous to block)
##   distance: float
##   block_id: int
func raycast(origin: Vector3, direction: Vector3, max_distance: float = 6.0) -> Dictionary:
	if not _is_finite_vector(origin) or not _is_finite_vector(direction) or not is_finite(max_distance):
		return _ray_miss(max_distance)
	if direction.length_squared() <= 0.0:
		return _ray_miss(max_distance)

	var start := Vector3i(
		int(floor(origin.x)),
		int(floor(origin.y)),
		int(floor(origin.z))
	)
	var start_block := get_block(start.x, start.y, start.z)
	if start_block != AIR:
		return {
			"hit": true,
			"block": [start.x, start.y, start.z],
			"previous": [start.x, start.y, start.z],
			"normal": [0, 0, 0],
			"distance": 0.0,
			"block_id": start_block,
		}

	if max_distance <= 0.0:
		return _ray_miss(max_distance)

	var dir := direction.normalized()
	var step := Vector3i(
		1 if dir.x > 0.0 else (-1 if dir.x < 0.0 else 0),
		1 if dir.y > 0.0 else (-1 if dir.y < 0.0 else 0),
		1 if dir.z > 0.0 else (-1 if dir.z < 0.0 else 0)
	)

	var t_max := Vector3(INF, INF, INF)
	var t_delta := Vector3(INF, INF, INF)

	if step.x != 0:
		if step.x > 0:
			t_max.x = (float(start.x + 1) - origin.x) / dir.x
		else:
			t_max.x = (float(start.x) - origin.x) / dir.x
		t_delta.x = 1.0 / absf(dir.x)
	if step.y != 0:
		if step.y > 0:
			t_max.y = (float(start.y + 1) - origin.y) / dir.y
		else:
			t_max.y = (float(start.y) - origin.y) / dir.y
		t_delta.y = 1.0 / absf(dir.y)
	if step.z != 0:
		if step.z > 0:
			t_max.z = (float(start.z + 1) - origin.z) / dir.z
		else:
			t_max.z = (float(start.z) - origin.z) / dir.z
		t_delta.z = 1.0 / absf(dir.z)

	var cell := start
	for _iteration in range(MAX_RAY_STEPS):
		var distance := t_max.x
		var axis := 0
		if t_max.y < distance:
			distance = t_max.y
			axis = 1
		if t_max.z < distance:
			distance = t_max.z
			axis = 2
		if not is_finite(distance) or distance > max_distance:
			return _ray_miss(max_distance)

		var previous := cell
		if axis == 0:
			cell.x += step.x
			t_max.x += t_delta.x
		elif axis == 1:
			cell.y += step.y
			t_max.y += t_delta.y
		else:
			cell.z += step.z
			t_max.z += t_delta.z

		var block_id := get_block(cell.x, cell.y, cell.z)
		if block_id != AIR:
			return {
				"hit": true,
				"block": [cell.x, cell.y, cell.z],
				"previous": [previous.x, previous.y, previous.z],
				"normal": [
					cell.x - previous.x,
					cell.y - previous.y,
					cell.z - previous.z,
				],
				"distance": distance,
				"block_id": block_id,
			}

	return _ray_miss(max_distance)


func hash() -> String:
	var context := HashingContext.new()
	context.start(HashingContext.HASH_SHA256)
	var header := "%d:%d:%d:%d:%d;" % [width, height, depth, world_seed, blocks.size()]
	context.update(header.to_utf8_buffer())
	context.update(blocks)
	return context.finish().hex_encode()


# ---------------------------------------------------------------------------
# Generation helpers
# ---------------------------------------------------------------------------

func _ensure_storage() -> void:
	var volume := width * height * depth
	if blocks.size() != volume:
		blocks.resize(volume)
	if base_blocks.size() != volume:
		base_blocks.resize(volume)


func _spawn_center_x() -> int:
	return int(floor(float(width) * 0.5))


func _spawn_center_z() -> int:
	return int(floor(float(depth) * 0.5))


## A smooth, seed-dependent landscape. The wave sum gives broad hills and
## valleys; the hash detail breaks up any obvious repetition between octaves.
func _surface_height(x: int, z: int) -> int:
	var max_top := maxi(0, height - 3)
	var min_top := mini(3, max_top)
	var amplitude := clampf(float(max_top) * 0.55, 0.0, 5.5)
	var base := float(min_top) + amplitude * 0.55 + 0.5
	var phase := float(posmod(world_seed, 100003)) * 0.00137

	var wave := (
		sin(float(x) * 0.23 + phase) * 0.45
		+ cos(float(z) * 0.19 + phase * 1.7) * 0.35
		+ sin(float(x + z) * 0.11 + phase * 0.6) * 0.20
	)
	var detail := (_hash01(world_seed, x, z) - 0.5) * 0.35
	var normalized := clampf((wave + detail) / 1.35, -1.0, 1.0)
	var top := int(round(base + normalized * amplitude))
	return clampi(top, min_top, max_top)


func _place_trees() -> void:
	var target_count := clampi(int((width * depth) / 140), 1, 9)
	var placed := 0
	var occupied: Dictionary = {}
	var margin_x := mini(2, maxi(0, int((width - 1) * 0.5)))
	var margin_z := mini(2, maxi(0, int((depth - 1) * 0.5)))
	var span_x := maxi(1, width - margin_x * 2)
	var span_z := maxi(1, depth - margin_z * 2)

	for tree_index in range(target_count):
		var tx := margin_x + _rand_below(world_seed, 101 + tree_index, span_x)
		var tz := margin_z + _rand_below(world_seed, 211 + tree_index, span_z)
		tx = clampi(tx, 0, width - 1)
		tz = clampi(tz, 0, depth - 1)
		if _near_spawn(tx, tz, 2):
			continue
		var key := Vector2i(tx, tz)
		if occupied.has(key):
			continue
		var trunk_height := 3 + int(_hash01(world_seed, 307 + tree_index, 0) * 2.0)
		if _try_place_tree(tx, tz, trunk_height):
			occupied[key] = true
			placed += 1

	if placed == 0:
		# Guarantee a tree even for awkward seeds or small worlds by scanning
		# for any column with enough headroom and progressively shortening it.
		for z in range(depth):
			for x in range(width):
				if _near_spawn(x, z, 2):
					continue
				var top := _surface_height(x, z)
				for trunk_height in [3, 2, 1]:
					if top + trunk_height + 1 < height and _try_place_tree(x, z, trunk_height):
						return


func _try_place_tree(tx: int, tz: int, trunk_height: int) -> bool:
	if not is_inside(tx, 0, tz):
		return false
	var top := _surface_height(tx, tz)
	var trunk_top := top + trunk_height
	if trunk_height < 1 or trunk_top + 1 >= height:
		return false

	for offset in range(1, trunk_height + 1):
		set_block(tx, top + offset, tz, LOG)

	for dy in range(-1, 2):
		var layer_y := trunk_top + dy
		if layer_y <= top or layer_y < 0 or layer_y >= height:
			continue
		var radius := 2 if dy < 0 else 1
		for dx in range(-radius, radius + 1):
			for dz in range(-radius, radius + 1):
				if dx == 0 and dz == 0:
					continue
				if dy >= 0 and absi(dx) == radius and absi(dz) == radius:
					continue
				var lx := tx + dx
				var lz := tz + dz
				if not is_inside(lx, layer_y, lz):
					continue
				var existing := get_block(lx, layer_y, lz)
				if existing == AIR or existing == LEAVES:
					set_block(lx, layer_y, lz, LEAVES)
	return true


func _clear_spawn_region() -> void:
	var center_x := _spawn_center_x()
	var center_z := _spawn_center_z()
	for dz in range(-2, 3):
		for dx in range(-2, 3):
			var x := center_x + dx
			var z := center_z + dz
			if x < 0 or x >= width or z < 0 or z >= depth:
				continue
			var top := _surface_height(x, z)
			var start_y := mini(height, top + 1)
			for y in range(start_y, height):
				blocks[index(x, y, z)] = AIR


func _near_spawn(x: int, z: int, radius: int) -> bool:
	return (
		absi(x - _spawn_center_x()) <= radius
		and absi(z - _spawn_center_z()) <= radius
	)


func _rand_below(seed_value: int, salt: int, limit: int) -> int:
	if limit <= 1:
		return 0
	var mixed := _mix32(seed_value ^ (salt * 374761393))
	return int(mixed % limit)


func _hash01(seed_value: int, a: int, b: int) -> float:
	var mixed := _mix32(seed_value)
	mixed = _mix32(mixed ^ (a * 73856093))
	mixed = _mix32(mixed ^ (b * 19349663))
	return float(mixed & 0xFFFF) / 65535.0


func _mix32(value: int) -> int:
	var mixed := value & 0xFFFFFFFF
	mixed = (mixed ^ (mixed >> 16)) * 0x45D9F3B
	mixed = mixed & 0xFFFFFFFF
	mixed = (mixed ^ (mixed >> 16)) * 0x45D9F3B
	mixed = mixed & 0xFFFFFFFF
	mixed = mixed ^ (mixed >> 16)
	return mixed & 0xFFFFFFFF


# ---------------------------------------------------------------------------
# Save/raycast helpers
# ---------------------------------------------------------------------------

## Returns an int for integer-valued numbers, or null for anything else.
## JSON round trips represent whole numbers as floats, so integral floats are
## accepted while fractional values, strings, booleans, and null are rejected.
func _integer_value(value):
	match typeof(value):
		TYPE_INT:
			return value
		TYPE_FLOAT:
			var number := float(value)
			if not is_finite(number):
				return null
			if number != floor(number):
				return null
			if absf(number) > 9.0e18:
				return null
			return int(number)
		_:
			return null


func _is_finite_vector(value: Vector3) -> bool:
	return is_finite(value.x) and is_finite(value.y) and is_finite(value.z)


func _ray_miss(max_distance: float) -> Dictionary:
	return {
		"hit": false,
		"block": [],
		"previous": [],
		"normal": [],
		"distance": max_distance,
		"block_id": AIR,
	}

