	var result: Dictionary = {}
	for block_id in BLOCK_NAMES:
		result[String(BLOCK_NAMES[block_id])] = 0
	for value in blocks:
		var block_id := int(value)
		if BLOCK_NAMES.has(block_id):
			var key := String(BLOCK_NAMES[block_id])
			result[key] = int(result[key]) + 1
	return result


## Changes relative to the generated baseline, in deterministic y/z/x order.
## Removed baseline blocks appear with id 0.
func changed_blocks() -> Array:
	var result: Array = []
	var volume := mini(blocks.size(), base_blocks.size())
	for y in range(height):
		for z in range(depth):
			for x in range(width):
				var cell := index(x, y, z)
				if cell >= volume:
					continue
				var current := int(blocks[cell])
				var baseline := int(base_blocks[cell])
				if current != baseline:
					result.append({"x": x, "y": y, "z": z, "id": current})
	return result


func to_save_dict() -> Dictionary:
	return {
		"version": SAVE_VERSION,
		"world": {
			"width": width,
			"height": height,
			"depth": depth,
			"seed": world_seed,
		},
		"changes": changed_blocks(),
	}


## Validate and apply a save document atomically. Invalid input returns false
## and leaves the current world untouched.
##
## The parameter is intentionally untyped so that non-dictionary input (which
## the contract requires us to reject) arrives here as a value instead of
## triggering a typed-argument error before validation can run.
func apply_save(data) -> bool:
	if typeof(data) != TYPE_DICTIONARY:
		return false
	var document: Dictionary = data

	var version = _integer_value(document.get("version"))
	if version == null or int(version) != SAVE_VERSION:
		return false

	var world = document.get("world")
	if typeof(world) != TYPE_DICTIONARY:
		return false
	var world_document: Dictionary = world

	var saved_width = _integer_value(world_document.get("width"))
	var saved_height = _integer_value(world_document.get("height"))
	var saved_depth = _integer_value(world_document.get("depth"))
	var saved_seed = _integer_value(world_document.get("seed"))
	if saved_width == null or saved_height == null or saved_depth == null or saved_seed == null:
		return false
	if int(saved_width) != width or int(saved_height) != height or int(saved_depth) != depth:
		return false

	var changes = document.get("changes")
	if typeof(changes) != TYPE_ARRAY:
		return false
	var change_list: Array = changes
	if change_list.size() > width * height * depth:
		return false

	# Parse every cell before touching the live world. The temporary records
	# keep the apply phase free of any validation failure paths.
	var validated: Array = []
	for entry in change_list:
		if typeof(entry) != TYPE_DICTIONARY:
			return false
		var change: Dictionary = entry
		var cx = _integer_value(change.get("x"))
		var cy = _integer_value(change.get("y"))
		var cz = _integer_value(change.get("z"))
		var block_id = _integer_value(change.get("id"))
		if cx == null or cy == null or cz == null or block_id == null:
			return false
		if not is_inside(int(cx), int(cy), int(cz)):
			return false
		if int(block_id) < AIR or int(block_id) > LEAVES:
			return false
		validated.append({
			"x": int(cx),
			"y": int(cy),
			"z": int(cz),
			"id": int(block_id),
		})

	# Validation passed; regenerate the saved baseline and replay the edits.
	generate(int(saved_seed))
	for change in validated:
		set_block(int(change["x"]), int(change["y"]), int(change["z"]), int(change["id"]))
	return true


## Amanatides-Woo style grid traversal. Returns:
##   hit: bool
##   block: [x, y, z] (empty when no hit)
##   previous: [x, y, z] (empty when no hit)
##   normal: [x, y, z] (axis from previous to block)
##   distance: float
##   block_id: int
func raycast(origin: Vector3, direction: Vector3, max_distance: float = 6.0) -> Dictionary:
	if not _is_finite_vector(origin) or not _is_finite_vector(direction) or not is_finite(max_distance):
		return _ray_miss(max_distance)
	if direction.length_squared() <= 0.0:
		return _ray_miss(max_distance)

	var start := Vector3i(
		int(floor(origin.x)),
		int(floor(origin.y)),
		int(floor(origin.z))
	)
	var start_block := get_block(start.x, start.y, start.z)
	if start_block != AIR:
		return {
			"hit": true,
			"block": [start.x, start.y, start.z],
			"previous": [start.x, start.y, start.z],
			"normal": [0, 0, 0],
			"distance": 0.0,
			"block_id": start_block,
		}

	if max_distance <= 0.0:
		return _ray_miss(max_distance)

	var dir := direction.normalized()
	var step := Vector3i(
		1 if dir.x > 0.0 else (-1 if dir.x < 0.0 else 0),
		1 if dir.y > 0.0 else (-1 if dir.y < 0.0 else 0),
		1 if dir.z > 0.0 else (-1 if dir.z < 0.0 else 0)
	)

	var t_max := Vector3(INF, INF, INF)
	var t_delta := Vector3(INF, INF, INF)

	if step.x != 0:
		if step.x > 0:
			t_max.x = (float(start.x + 1) - origin.x) / dir.x
		else:
			t_max.x = (float(start.x) - origin.x) / dir.x
		t_delta.x = 1.0 / absf(dir.x)
	if step.y != 0:
		if step.y > 0:
			t_max.y = (float(start.y + 1) - origin.y) / dir.y
		else:
			t_max.y = (float(start.y) - origin.y) / dir.y
		t_delta.y = 1.0 / absf(dir.y)
	if step.z != 0:
		if step.z > 0:
			t_max.z = (float(start.z + 1) - origin.z) / dir.z
		else:
			t_max.z = (float(start.z) - origin.z) / dir.z
		t_delta.z = 1.0 / absf(dir.z)

	var cell := start
	for _iteration in range(MAX_RAY_STEPS):
		var distance := t_max.x
		var axis := 0
		if t_max.y < distance:
			distance = t_max.y
			axis = 1
		if t_max.z < distance:
			distance = t_max.z
			axis = 2
		if not is_finite(distance) or distance > max_distance:
			return _ray_miss(max_distance)

		var previous := cell
		if axis == 0:
			cell.x += step.x
			t_max.x += t_delta.x
		elif axis == 1:
			cell.y += step.y
			t_max.y += t_delta.y
		else:
			cell.z += step.z
			t_max.z += t_delta.z

		var block_id := get_block(cell.x, cell.y, cell.z)
		if block_id != AIR:
			return {
				"hit": true,
				"block": [cell.x, cell.y, cell.z],
				"previous": [previous.x, previous.y, previous.z],
				"normal": [
					cell.x - previous.x,
					cell.y - previous.y,
					cell.z - previous.z,
				],
				"distance": distance,
				"block_id": block_id,
			}

	return _ray_miss(max_distance)


func hash() -> String:
	var context := HashingContext.new()
	context.start(HashingContext.HASH_SHA256)
	var header := "%d:%d:%d:%d:%d;" % [width, height, depth, world_seed, blocks.size()]
	context.update(header.to_utf8_buffer())
	context.update(blocks)
	return context.finish().hex_encode()


