# Generation helpers
# ---------------------------------------------------------------------------

func _ensure_storage() -> void:
	var volume := width * height * depth
	if blocks.size() != volume:
		blocks.resize(volume)
	if base_blocks.size() != volume:
		base_blocks.resize(volume)


func _spawn_center_x() -> int:
	return int(floor(float(width) * 0.5))


func _spawn_center_z() -> int:
	return int(floor(float(depth) * 0.5))


## A smooth, seed-dependent landscape. The wave sum gives broad hills and
## valleys; the hash detail breaks up any obvious repetition between octaves.
func _surface_height(x: int, z: int) -> int:
	var max_top := maxi(0, height - 3)
	var min_top := mini(3, max_top)
	var amplitude := clampf(float(max_top) * 0.55, 0.0, 5.5)
	var base := float(min_top) + amplitude * 0.55 + 0.5
	var phase := float(posmod(world_seed, 100003)) * 0.00137

	var wave := (
		sin(float(x) * 0.23 + phase) * 0.45
		+ cos(float(z) * 0.19 + phase * 1.7) * 0.35
		+ sin(float(x + z) * 0.11 + phase * 0.6) * 0.20
	)
	var detail := (_hash01(world_seed, x, z) - 0.5) * 0.35
	var normalized := clampf((wave + detail) / 1.35, -1.0, 1.0)
	var top := int(round(base + normalized * amplitude))
	return clampi(top, min_top, max_top)


func _place_trees() -> void:
	var target_count := clampi(int((width * depth) / 140), 1, 9)
	var placed := 0
	var occupied: Dictionary = {}
	var margin_x := mini(2, maxi(0, int((width - 1) * 0.5)))
	var margin_z := mini(2, maxi(0, int((depth - 1) * 0.5)))
	var span_x := maxi(1, width - margin_x * 2)
	var span_z := maxi(1, depth - margin_z * 2)

	for tree_index in range(target_count):
		var tx := margin_x + _rand_below(world_seed, 101 + tree_index, span_x)
		var tz := margin_z + _rand_below(world_seed, 211 + tree_index, span_z)
		tx = clampi(tx, 0, width - 1)
		tz = clampi(tz, 0, depth - 1)
		if _near_spawn(tx, tz, 2):
			continue
		var key := Vector2i(tx, tz)
		if occupied.has(key):
			continue
		var trunk_height := 3 + int(_hash01(world_seed, 307 + tree_index, 0) * 2.0)
		if _try_place_tree(tx, tz, trunk_height):
			occupied[key] = true
			placed += 1

	if placed == 0:
		# Guarantee a tree even for awkward seeds or small worlds by scanning
		# for any column with enough headroom and progressively shortening it.
		for z in range(depth):
			for x in range(width):
				if _near_spawn(x, z, 2):
					continue
				var top := _surface_height(x, z)
				for trunk_height in [3, 2, 1]:
					if top + trunk_height + 1 < height and _try_place_tree(x, z, trunk_height):
						return


func _try_place_tree(tx: int, tz: int, trunk_height: int) -> bool:
	if not is_inside(tx, 0, tz):
		return false
	var top := _surface_height(tx, tz)
	var trunk_top := top + trunk_height
	if trunk_height < 1 or trunk_top + 1 >= height:
		return false

	for offset in range(1, trunk_height + 1):
		set_block(tx, top + offset, tz, LOG)

	for dy in range(-1, 2):
		var layer_y := trunk_top + dy
		if layer_y <= top or layer_y < 0 or layer_y >= height:
			continue
		var radius := 2 if dy < 0 else 1
		for dx in range(-radius, radius + 1):
			for dz in range(-radius, radius + 1):
				if dx == 0 and dz == 0:
					continue
				if dy >= 0 and absi(dx) == radius and absi(dz) == radius:
					continue
				var lx := tx + dx
				var lz := tz + dz
				if not is_inside(lx, layer_y, lz):
					continue
				var existing := get_block(lx, layer_y, lz)
				if existing == AIR or existing == LEAVES:
					set_block(lx, layer_y, lz, LEAVES)
	return true


func _clear_spawn_region() -> void:
	var center_x := _spawn_center_x()
	var center_z := _spawn_center_z()
	for dz in range(-2, 3):
		for dx in range(-2, 3):
			var x := center_x + dx
			var z := center_z + dz
			if x < 0 or x >= width or z < 0 or z >= depth:
				continue
			var top := _surface_height(x, z)
			var start_y := mini(height, top + 1)
			for y in range(start_y, height):
				blocks[index(x, y, z)] = AIR


func _near_spawn(x: int, z: int, radius: int) -> bool:
	return (
		absi(x - _spawn_center_x()) <= radius
		and absi(z - _spawn_center_z()) <= radius
	)


func _rand_below(seed_value: int, salt: int, limit: int) -> int:
	if limit <= 1:
		return 0
	var mixed := _mix32(seed_value ^ (salt * 374761393))
	return int(mixed % limit)


func _hash01(seed_value: int, a: int, b: int) -> float:
	var mixed := _mix32(seed_value)
	mixed = _mix32(mixed ^ (a * 73856093))
	mixed = _mix32(mixed ^ (b * 19349663))
	return float(mixed & 0xFFFF) / 65535.0


func _mix32(value: int) -> int:
	var mixed := value & 0xFFFFFFFF
	mixed = (mixed ^ (mixed >> 16)) * 0x45D9F3B
	mixed = mixed & 0xFFFFFFFF
	mixed = (mixed ^ (mixed >> 16)) * 0x45D9F3B
	mixed = mixed & 0xFFFFFFFF
	mixed = mixed ^ (mixed >> 16)
	return mixed & 0xFFFFFFFF


